{
  "findings": [
    {
      "ref": "[D512]",
      "area": "contact",
      "claim": "A parent reports that strangers can message or voice chat with your child in Google Classroom.",
      "stance": "risk",
      "quote": "Kids can interact with other students and even teachers by text and video using Hangouts or the chat function in Meet."
    },
    {
      "ref": "[D512]",
      "area": "money",
      "claim": "The text does not mention any in-app purchases, loot boxes, pay-to-win, or subscription traps.",
      "stance": "neutral",
      "quote": "Google Classroom is a class-organization platform that incorporates Google's core products (Google Docs, Sheets, Slides, Drive, etc.) so students can access everything they need for a class, including homework assignments, group projects, files, and even Google Hangouts to chat with the teacher or the entire class."
    },
    {
      "ref": "[D512]",
      "area": "data",
      "claim": "A parent reports that Google can collect student data from some Classroom tools, such as YouTube, if they're enabled.",
      "stance": "risk",
      "quote": "Classroom allows students to see what's due, complete assignments, post messages, and more in virtual classes set up by their teachers. The fact that it's paperless and offers built-in opportunities for kids to practice responsible digital skills are great bonuses. But Google Classroom does invite some risks, including data tracking, potential contact with strangers, and even cyberbullying. While Google has stricter privacy practices for its educational apps, it can collect student data from some of the Classroom tools, such as YouTube, if they're enabled."
    },
    {
      "ref": "[D512]",
      "area": "age_gating",
      "claim": "A parent reports that the age gate works in practice, but the text does not provide specific evidence of its effectiveness.",
      "stance": "neutral",
      "quote": "Google pitches the platform to teachers as \"mission control for your classroom\" -- and it definitely streamlines homework, remote learning, and organization. But as more schools move toward using Google Classroom, it's a good idea to familiarize yourself with its capabilities so you can best support your kid's online learning."
    },
    {
      "ref": "[D512]",
      "area": "content",
      "claim": "A parent reports that reviewers have noted the platform can be used for chatting and potential cyberbullying.",
      "stance": "risk",
      "quote": "Kids can potentially see other students' work within the platform, too. If they're taking a quiz in Google Forms, however, teachers can disable access to other resources using a feature called Locked mode. As for chatting, yes. Kids can interact with other students and even teachers by text and video using Hangouts or the chat function in Meet. Chatting can be a distraction, but there have also been some reports of kids cyberbullying other students in Google Docs shared for group projects."
    },
    {
      "ref": "[D512]",
      "area": "developer_record",
      "claim": "The text does not mention any fines, breaches, lawsuits, or regulatory actions involving the developer.",
      "stance": "neutral",
      "quote": "Google Classroom is part of Google's Workspace for Education (formerly called G Suite) and includes optional \"Additional Services,\" including YouTube and Maps, which a school administrator can choose to enable as part of your kid's Classroom tools."
    }
  ]
}
